// De onde sai a lista de páginas que a Glória vai ler.
//
// Primeiro tenta o sitemap do site: assim, LP nova entra sozinha na próxima
// carga e ninguém precisa lembrar de vir aqui. Se o sitemap não existir (ou
// mudar de endereço), a lista de baixo assume.

const LISTA_MANUAL = [
  // Cole aqui as páginas, uma por linha, se o sitemap falhar:
  // 'https://setuforeuvouviagens.com.br/islandia',
  // 'https://setuforeuvouviagens.com.br/patagonia',
];

// Páginas que não ajudam a responder lead e só gastam embedding.
const IGNORAR = /(politica|privacidade|termos|cookies|obrigado|thank|login|admin|\.(jpg|png|webp|pdf|xml)$)/i;

const xml = String($json.data || $json.body || '');
const doSitemap = [...xml.matchAll(/<loc>\s*([^<]+?)\s*<\/loc>/gi)].map((m) => m[1]);

const urls = [...new Set((doSitemap.length ? doSitemap : LISTA_MANUAL))]
  .map((u) => String(u).trim())
  .filter((u) => /^https?:\/\//.test(u) && !IGNORAR.test(u));

if (!urls.length) {
  throw new Error(
    'Nenhuma página pra ler. O sitemap não respondeu e a LISTA_MANUAL está vazia — ' +
    'abra este nó e cole os endereços das LPs.'
  );
}

return urls.map((url) => ({ json: { url } }));

// HTML vira texto de leitura.
//
// Sem isto, o que entra no banco é <div class="hero"> — e a IA passa a
// responder com pedaço de CSS. Não é bonito, mas é o suficiente pra uma LP:
// tira script e style, troca as tags por espaço e desfaz as entidades.

const url = $('Lista de páginas').item.json.url;
const html = String($json.data || $json.body || '');

const semLixo = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');

const titulo = (semLixo.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] || url).trim();

const texto = semLixo
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|section|h[1-6]|li|tr)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n\s*\n+/g, '\n\n')
  .trim();

// Página curta demais é erro de carregamento (site que monta tudo no
// navegador, 404 estilizado). Gravar isso ensinaria a IA a não saber nada.
if (texto.length < 400) {
  return [{ json: { url, titulo, texto: '', ignorada: true, motivo: 'pagina_curta_demais', tamanho: texto.length } }];
}

return [{ json: { url, titulo, texto, ignorada: false, tamanho: texto.length } }];

// O que entrou nesta carga.
const itens = $input.all().map((i) => i.json);
return [{ json: {
  paginas_processadas: itens.length,
  quando: $now.toISO(),
  aviso: 'Confira no Supabase: select count(*), metadata->>\'url\' from gloria_documents group by 2 order by 1 desc;',
} }];
